(()=>{const t=window.BarfordMemberFlow,o=window.BarfordSupabase,a=document.getElementById("memberPayments"),n=new URLSearchParams(location.search).get("event");if(!t||!a)return;if(n){const s=document.getElementById("paymentBack");s.href=t.eventUrl(n),s.textContent="\u2190 Back to my event"}async function c(){try{const s=await t.request(o.auth.getSession());if(!s.session){a.innerHTML=`<article class="simple-card"><h2>Sign in to see your payments</h2><a class="button button-primary" href="${t.loginUrl(location.href)}">Sign in</a></article>`;return}const l=o.from("rsvps").select("event_id,status,payment_status").eq("member_id",s.session.user.id),m=await t.request(n?l.eq("event_id",n):l),p=n?[n]:m.filter(e=>e.status==="playing"||["paid","refunded","waived"].includes(e.payment_status)).map(e=>e.event_id);if(!p.length){a.innerHTML='<article class="simple-card"><h2>No event payments to show</h2><p>Your payments will appear here when you book an event.</p><a class="button button-primary" href="events.html">View events</a></article>';return}const d=await t.request(o.from("events").select("*").in("id",p).order("event_date"));a.innerHTML=d.map(e=>{const i=m.find(u=>u.event_id===e.id),r=t.payment(e,i);return`<article class="simple-card"><h2>${t.esc(e.name)}</h2><p>${t.esc(t.date(e.event_date))}</p><p class="simple-payment-state"><strong>${t.esc(r.label)}</strong></p>${r.due?"<p>Online payment is not available yet. Ask the committee for payment instructions. They will mark your payment as paid when it is confirmed.</p>":e.status==="cancelled"&&i?.payment_status==="paid"?"<p>If you need to discuss a refund, please ask the committee.</p>":i?.status==="reserve"?"<p>You do not need to pay while waiting for a place.</p>":""}${r.due?`<button class="button button-primary" data-payment-help="${t.esc(e.id)}">Ask for payment details</button><details class="simple-details"><summary>Already paid?</summary><p>Your payment has not yet been marked as paid. Ask the committee to check it before making another payment.</p><button class="button button-outline" data-payment-check="${t.esc(e.id)}">Ask the committee to check</button></details>`:""}<a class="button button-outline" href="${t.eventUrl(e.id)}">Back to event</a></article>`}).join("")||"<p>The event could not be found.</p>",a.querySelectorAll("[data-payment-help],[data-payment-check]").forEach(e=>e.onclick=()=>t.contact(d.find(i=>i.id===(e.dataset.paymentHelp||e.dataset.paymentCheck)),e.dataset.paymentCheck?"check a payment I have already made":"get the payment details"))}catch{a.innerHTML='<article class="simple-card"><h2>Payments could not be checked</h2><p>Please try again to see the latest payment status.</p><button class="button button-primary" id="retryPayments">Try again</button></article>',a.querySelector("#retryPayments").onclick=c}}c()})();
